{
  "items": [
    {
      "name": "Polynomial.rootMultiplicity",
      "module_name": "Mathlib.Algebra.Polynomial.Div",
      "kind": "definition",
      "type": "{R : Type u} → [inst : Ring R] → R → Polynomial R → ℕ"
    },
    {
      "name": "den_dvd_of_is_root",
      "module_name": "Mathlib.RingTheory.Polynomial.RationalRoot",
      "kind": "theorem",
      "type": "∀ {A : Type u_1} {K : Type u_2} [inst : CommRing A] [inst_1 : IsDomain A] [inst_2 : UniqueFactorizationMonoid A]\n  [inst_3 : Field K] [inst_4 : Algebra A K] [inst_5 : IsFractionRing A K] {p : Polynomial A} {r : K},\n  (Polynomial.aeval r) p = 0 → ↑(IsFractionRing.den A r) ∣ p.leadingCoeff"
    },
    {
      "name": "num_dvd_of_is_root",
      "module_name": "Mathlib.RingTheory.Polynomial.RationalRoot",
      "kind": "theorem",
      "type": "∀ {A : Type u_1} {K : Type u_2} [inst : CommRing A] [inst_1 : IsDomain A] [inst_2 : UniqueFactorizationMonoid A]\n  [inst_3 : Field K] [inst_4 : Algebra A K] [inst_5 : IsFractionRing A K] {p : Polynomial A} {r : K},\n  (Polynomial.aeval r) p = 0 → IsFractionRing.num A r ∣ p.coeff 0"
    },
    {
      "name": "Polynomial.card_roots",
      "module_name": "Mathlib.Algebra.Polynomial.Roots",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : CommRing R] [inst_1 : IsDomain R] {p : Polynomial R}, p ≠ 0 → ↑p.roots.card ≤ p.degree"
    },
    {
      "name": "Polynomial.rootMultiplicity_le_rootMultiplicity_of_dvd",
      "module_name": "Mathlib.Algebra.Polynomial.Div",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : CommRing R] {p q : Polynomial R},\n  q ≠ 0 → p ∣ q → ∀ (x : R), Polynomial.rootMultiplicity x p ≤ Polynomial.rootMultiplicity x q"
    },
    {
      "name": "Polynomial.rootMultiplicity_le_one_of_separable",
      "module_name": "Mathlib.FieldTheory.Separable",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : CommRing R] [Nontrivial R] {p : Polynomial R},\n  p.Separable → ∀ (x : R), Polynomial.rootMultiplicity x p ≤ 1"
    }
  ]
}
